<script setup lang="ts">import {ref,computed,onMounted} from 'vue';import {go} from '../router';import {studies} from '../stores/studies';import {datasets} from '../stores/datasets';import {instruments} from '../stores/instruments';import {runs} from '../stores/runs';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {analysisMethodLabels} from '../constants/enums';import type {AnalysisMethod} from '../types/domain';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),dataset=ref('demo-dataset'),instrument=ref('demo-instrument'),ratio=ref(2.25),tolerance=ref(2),method=ref<AnalysisMethod>('difference'),relativeTolerance=ref(10);const isLog=computed(()=>method.value==='log_ratio');const {error,busy,act}=useTask();onMounted(()=>Promise.all([studies.load(),datasets.load(),instruments.load()]));function submit(){act(async()=>{const body:Record<string,unknown>={name:name.value,dataset_id:dataset.value,instrument_id:instrument.value,variance_ratio:ratio.value,tolerance:tolerance.value,analysis_method:method.value};if(isLog.value)body.relative_tolerance=relativeTolerance.value;await studies.create(body);name.value=''})}function execute(id:string){act(async()=>{const run=await runs.create({study_id:id});go('/results?run='+run.id)})}function methodLabel(m:string){return analysisMethodLabels[m]??m}</script><template><PageHeading index="03 / 研究设定" title="误差方差比，是输入，不是拟合结论。" note="λ=var(y测量误差)/var(x测量误差)，由外部重复测量或计量依据提供。可在原差值与对数比值两种一致性口径间选择；讨论容差不改变界限。"/><Notice :message="error"/><div class="two-col"><section><article v-for="r in studies.items.value" :key="r.id" class="study-row"><p class="eyebrow">CALIBRATION STUDY</p><h2>{{r.name}}</h2><dl><div><dt>分析方式</dt><dd style="font-size:17px">{{methodLabel(r.analysis_method||'difference')}}</dd></div><div><dt>方差比 λ</dt><dd>{{r.variance_ratio}}</dd></div><div v-if="r.analysis_method==='log_ratio'"><dt>相对容差</dt><dd>±{{r.relative_tolerance}}%</dd></div><div v-else><dt>讨论容差 ±</dt><dd>{{r.tolerance}}</dd></div><div><dt>BA样本SD</dt><dd>ddof=1</dd></div></dl><button v-if="canWrite()" :disabled="busy" @click="execute(r.id)">执行后台校准 →</button></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>新建校准研究</h2><label>研究名称<input v-model="name" required minlength="2"></label><label>配对批次<select v-model="dataset"><option v-for="r in datasets.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>探头组合<select v-model="instrument"><option v-for="r in instruments.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>一致性分析方式<select v-model="method"><option value="difference">原差值 Bland–Altman（d=y−x，容差按同单位绝对差）</option><option value="log_ratio">对数比值 Bland–Altman（ln(Y/X)，容差按相对偏差百分比）</option></select></label><label>误差方差比 λ<input type="number" v-model.number="ratio" min=".000001" max="1000000" step="any" required></label><label v-if="isLog">相对讨论容差（相对偏差 %）<input type="number" v-model.number="relativeTolerance" min="0.000001" max="100" step="any" required></label><label v-else>讨论容差（同读数单位）<input type="number" v-model.number="tolerance" min=".000001" max="1000000" step="any" required></label><p v-if="isLog" class="form-hint">对数口径要求全部读数严格为正；含零或负值的批次整次运行失败。几何均比与比值界限由 ln(Y/X) 指数还原，Deming 仍使用原读数。</p><p v-else class="form-hint">高读数段差值波动随量级增大、绝对界限难以比较时，可改用对数比值口径。</p><button :disabled="busy">保存研究设定</button></form></div></template>
